/* The lookup and decoder below: SPDX-License-Identifier: AGPL-3.0-only. */
uint32_t dx_font16_glyph_count(void)
{
    return (uint32_t)(sizeof(dx_font16_glyphs) / sizeof(dx_font16_glyphs[0]));
}

const dx_font16_glyph_t *dx_font16_get_index(uint32_t index)
{
    return index < dx_font16_glyph_count() ? &dx_font16_glyphs[index] :
           (const dx_font16_glyph_t *)0;
}

const dx_font16_glyph_t *dx_font16_find(uint32_t codepoint)
{
    uint32_t lo = 0, hi = dx_font16_glyph_count();
    while (lo < hi) {
        uint32_t mid = lo + (hi - lo) / 2;
        if (dx_font16_glyphs[mid].codepoint < codepoint) lo = mid + 1;
        else hi = mid;
    }
    if (lo < dx_font16_glyph_count() && dx_font16_glyphs[lo].codepoint == codepoint)
        return &dx_font16_glyphs[lo];
    return (const dx_font16_glyph_t *)0;
}

int dx_utf8_next(const char **cursor, uint32_t *cp)
{
    const unsigned char *s;
    uint32_t value, minimum;
    unsigned int length, i;
    if (!cursor || !*cursor || !cp) return -1;
    s = (const unsigned char *)*cursor;
    if (!s[0]) { *cp = 0; return 0; }
    if (s[0] < 0x80) { *cp = s[0]; *cursor += 1; return 1; }
    if (s[0] >= 0xC2 && s[0] <= 0xDF) {
        value = s[0] & 0x1F; length = 2; minimum = 0x80;
    } else if (s[0] >= 0xE0 && s[0] <= 0xEF) {
        value = s[0] & 0x0F; length = 3; minimum = 0x800;
    } else if (s[0] >= 0xF0 && s[0] <= 0xF4) {
        value = s[0] & 0x07; length = 4; minimum = 0x10000;
    } else goto invalid;
    for (i = 1; i < length; ++i) {
        /* Sequential check stops at NUL, including truncated final sequences. */
        unsigned char next = s[i];
        if (!next || (next & 0xC0) != 0x80) goto invalid;
        value = (value << 6) | (next & 0x3F);
    }
    if (value < minimum || value > 0x10FFFF ||
        (value >= 0xD800 && value <= 0xDFFF)) goto invalid;
    *cp = value;
    *cursor += length;
    return 1;
invalid:
    *cp = 0xFFFD;
    *cursor += 1;
    return -1;
}
